import com.bridger.momentum.UpdatePrompt;
public final class UpdatePromptRegression {
 private static void check(boolean result,String why){if(!result)throw new AssertionError(why);}
 public static void main(String[] args){UpdatePrompt p=new UpdatePrompt();check(!p.ready(false,true,false,0),"No available update");check(p.ready(true,true,false,1),"Title/pause menu lost prompt");check(!p.ready(true,false,false,2),"Prompt interrupted gameplay");check(!p.ready(true,false,true,3),"Prompt opened without idle grace");check(!p.ready(true,false,true,1000000003L),"Idle grace shortened");check(!p.ready(true,false,false,1500000003L),"Moving/bridging/replay did not defer");check(!p.ready(true,false,true,2000000003L),"Idle timer did not restart");check(p.ready(true,false,true,4000000003L),"Quick server join permanently lost startup prompt");check(!p.ready(false,true,true,5000000003L),"Dismissed/disabled prompt reopened");check(UpdatePrompt.customTitle("org.polyfrost.oneclient.ui.MainMenuScreen"),"OneClient title unsupported");check(!UpdatePrompt.customTitle("org.polyfrost.oneclient.ui.LoginScreen"),"Login screen interrupted");System.out.println("PASS: late startup results survive server joins, support custom titles/pause, wait for idle and defer movement/bridges/replays/dismissal");}
}
